SET NOCOUNT ON;

IF OBJECT_ID('dbo.fact_games', 'U') IS NOT NULL DROP TABLE dbo.fact_games;
IF OBJECT_ID('dbo.fact_matches', 'U') IS NOT NULL DROP TABLE dbo.fact_matches;
IF OBJECT_ID('dbo.dim_tournaments', 'U') IS NOT NULL DROP TABLE dbo.dim_tournaments;
GO

CREATE TABLE dbo.dim_tournaments (
    tournament_id   VARCHAR(64) NOT NULL PRIMARY KEY,
    tournament_name NVARCHAR(255) NOT NULL,
    url_slug        VARCHAR(128) NULL,
    start_date      DATETIMEOFFSET NULL,
    city            NVARCHAR(128) NULL,
    state           NVARCHAR(64) NULL
);

CREATE TABLE dbo.fact_matches (
    match_id        VARCHAR(64) NOT NULL PRIMARY KEY,
    tournament_id   VARCHAR(64) NOT NULL,
    division        NVARCHAR(128) NULL,
    stage_type      VARCHAR(64) NULL,
    team1_name      NVARCHAR(255) NULL,
    team1_players   NVARCHAR(255) NULL,
    team2_name      NVARCHAR(255) NULL,
    team2_players   NVARCHAR(255) NULL,
    winner_team     NVARCHAR(255) NULL,
    winner_players  NVARCHAR(255) NULL,
    played_at       DATETIMEOFFSET NULL,
    CONSTRAINT FK_matches_tournament FOREIGN KEY (tournament_id) REFERENCES dbo.dim_tournaments(tournament_id)
);

CREATE TABLE dbo.fact_games (
    game_id         INT IDENTITY(1,1) PRIMARY KEY,
    match_id        VARCHAR(64) NOT NULL,
    game_number     INT NOT NULL,
    team1_score     INT NOT NULL,
    team2_score     INT NOT NULL,
    point_diff      INT NOT NULL,
    game_winner     NVARCHAR(255) NULL,
    CONSTRAINT FK_games_match FOREIGN KEY (match_id) REFERENCES dbo.fact_matches(match_id)
);
GO

CREATE INDEX IX_fact_matches_tournament ON dbo.fact_matches(tournament_id);
CREATE INDEX IX_fact_games_match ON dbo.fact_games(match_id);
